<!doctype html><html><head><meta charset="utf-8"><title>Invoice #{{$order->order_number}} — Chacha Prime</title><style>body{font-family:Arial,sans-serif;background:#f1f5f9;color:#111827;margin:0}.invoice{max-width:900px;margin:30px auto;background:#fff;padding:35px;box-shadow:0 8px 30px #0001}.head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:2px solid #111827;padding-bottom:20px}.logo{width:180px}.muted{color:#64748b;font-size:12px}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{padding:12px;border-bottom:1px solid #e5e7eb;text-align:left;font-size:12px}th{background:#f8fafc}.total{text-align:right;margin-top:20px}.codebox{display:flex;gap:30px;align-items:center;margin-top:28px;padding:18px;background:#f8fafc;border-radius:10px}.codebox canvas{background:#fff;padding:6px}.barcode{font-family:monospace;font-size:22px;letter-spacing:3px;font-weight:900}.actions{margin:15px auto;max-width:900px;display:flex;justify-content:flex-end}.actions button{padding:10px 16px;border:0;border-radius:8px;background:#111827;color:#fff}@media print{body{background:#fff}.invoice{margin:0;box-shadow:none}.actions{display:none}}</style><style>@media print{body{background:#fff}.invoice{box-shadow:none;margin:0;max-width:none}}.invoice-actions{display:flex;gap:8px;margin-bottom:18px}.invoice-actions a,.invoice-actions button{border:0;border-radius:9px;padding:9px 13px;background:#111827;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}@media(max-width:600px){.invoice{margin:0;padding:20px}.head{gap:12px}.codebox{flex-direction:column;align-items:flex-start}}</style></head><body><div class="actions"><button onclick="window.print()">Print / Save PDF</button></div><main class="invoice"><div class="head"><div><img class="logo" src="{{asset('images/chacha-logo.svg')}}" alt="Chacha Prime"><p class="muted">Premium B2B & B2C Marketplace</p></div><div><h2>INVOICE</h2><div class="muted">Invoice # CP-INV-{{$order->id}}</div><div class="muted">Order # {{$order->order_number}}</div><div class="muted">{{date('Y-m-d',strtotime($order->created_at))}}</div></div></div><table><thead><tr><th>Product</th><th>SKU</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody>@foreach($items as $item)<tr><td>{{$item->product_name}}</td><td>{{$item->sku}}</td><td>{{$item->quantity}}</td><td>{{$item->unit_price}} {{$order->currency}}</td><td>{{$item->subtotal}} {{$order->currency}}</td></tr>@endforeach</tbody></table><div class="total"><p>Subtotal: {{$order->subtotal}} {{$order->currency}}</p><p>Discount: {{$order->discount_total}} {{$order->currency}}</p><p>Shipping: {{$order->shipping_total}} {{$order->currency}}</p><h2>Grand Total: {{$order->grand_total}} {{$order->currency}}</h2></div><div class="codebox"><div><canvas id="qr" width="130" height="130"></canvas><div class="muted">Scan for secure order lookup</div></div><div><svg id="barcode"></svg><div class="muted">Order barcode</div></div></div><p class="muted" style="margin-top:25px">Payment: {{$order->payment_status}} • Fulfillment: {{$order->fulfillment_status}}</p></main><script src="https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jsbarcode@3.11.6/dist/JsBarcode.all.min.js"></script><script>JsBarcode("#barcode","{{$order->order_number}}",{format:"CODE128",displayValue:true,height:55,width:2,margin:0});</script><script>new QRCode(document.getElementById("qr"),{text:"{{route('customer.invoice',$order->id)}}",width:120,height:120});</script></body></html>